"""Publish verified generated bytes only beneath the configured dedicated directory."""
import hashlib,json,os,re,stat
from pathlib import Path
def publish(root,name,png,receipt,gid=None):
 if not Path(root).is_absolute() or not re.fullmatch(r"[0-9]{16,20}-[a-f0-9]{16}",name):raise ValueError("Invalid image publication scope")
 base=os.open(root,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
 try:
  st=os.fstat(base)
  if st.st_uid!=os.geteuid() or st.st_mode&0o022:raise ValueError("Untrusted image publication directory")
  os.mkdir(name,0o700,dir_fd=base);directory=os.open(name,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=base)
  try:
   if gid is not None:os.fchown(directory,-1,gid)
   os.fchmod(directory,0o750)
   for filename,data in [("image.png",png),("receipt.json",json.dumps(receipt,sort_keys=True).encode()+b"\n")]:
    fd=os.open(filename,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600,dir_fd=directory)
    try:
     if gid is not None:os.fchown(fd,-1,gid)
     with os.fdopen(fd,"wb",closefd=False) as f:f.write(data);f.flush();os.fsync(fd)
     os.fchmod(fd,0o440)
    finally:os.close(fd)
   os.fsync(directory)
  finally:os.close(directory)
  os.fsync(base)
 finally:os.close(base)
 # Report the real location under the configured root; WatooM-Code mounts the image
 # project tree at the same absolute path, so it resolves on the host and in chat.
 return {"path":str(Path(root)/name/"image.png"),"receipt":str(Path(root)/name/"receipt.json"),"sha256":hashlib.sha256(png).hexdigest(),"bytes":len(png)}
